function minimumSplits(nums) {
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  let count = 1;
  let current = nums[0];

  for (let i = 1; i < nums.length; i++) {
    current = gcd(current, nums[i]);
    if (current === 1) {
      count++;
      current = nums[i];
    }
  }
  return count;
}

