function minimumSplits(nums) {
  // best[j] = fewest pieces for the first j values; try every last piece nums[i..j-1].
  const n = nums.length;
  const divisor = (a, b) => { while (b) { const t = a % b; a = b; b = t; } return a; };
  const best = new Array(n + 1).fill(Infinity);
  best[0] = 0;
  for (let j = 1; j <= n; j++) {
    let g = 0;
    for (let i = j - 1; i >= 0; i--) {
      g = divisor(g, nums[i]);
      if (g > 1) best[j] = Math.min(best[j], best[i] + 1);
    }
  }
  return best[n];
}

