function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const primes = [2, 3, 5, 7, 11, 13];
  if (size === 'small') {
    const n = 1 + pick(8);
    // Small products of small primes share factors often, so pieces grow and break in varied ways.
    return [Array.from({ length: n }, () => {
      let value = primes[pick(4)];
      while (rand() < 0.5 && value * 7 <= 60) value *= primes[pick(4)];
      return value;
    })];
  }
  const n = 1500 + pick(501);
  const limit = 1e9;
  const nums = [];
  while (nums.length < n) {
    // A run built around one shared prime, sometimes with stray values that break it.
    const prime = rand() < 0.15 ? 999999937 : primes[pick(primes.length)];
    const run = 1 + pick(60);
    for (let k = 0; k < run && nums.length < n; k++) {
      if (rand() < 0.1) nums.push(2 + pick(limit - 1));
      else nums.push(prime * (1 + pick(Math.floor(limit / prime))));
    }
  }
  return [nums];
}
